import pytest
from datetime import date

from dispatch.case import scheduled


class _FrozenDate(date):
    """Stands in for ``date`` so that ``date.today()`` returns a fixed day."""

    @classmethod
    def today(cls):
        return cls(2025, 8, 18)


@pytest.mark.parametrize(
    "day,expected",
    [
        (date(2025, 8, 17), False),  # Sunday
        (date(2025, 8, 18), True),  # Monday
        (date(2025, 8, 19), False),  # Tuesday
        (date(2025, 8, 20), False),  # Wednesday
        (date(2025, 8, 21), False),  # Thursday
        (date(2025, 8, 22), False),  # Friday
        (date(2025, 8, 23), False),  # Saturday
    ],
)
def test_is_reminder_day(monkeypatch, day, expected):
    class FrozenDate(_FrozenDate):
        @classmethod
        def today(cls):
            return cls(day.year, day.month, day.day)

    monkeypatch.setattr(scheduled, "date", FrozenDate)

    assert scheduled._is_reminder_day() is expected

